#ifdef HOST_TESTING

        SetFunctionName("Matrix44(const fpu::Matrix44Template<FloatClassRHS> &_m)");

        ::rw::math::fpu::Matrix44Template<double> doubleUnalignedMatrix;
        ::rw::math::fpu::Matrix44Template<float> floatUnalignedMatrix;
        ::rw::math::fpu::Matrix44Template<double> doubleAlignedMatrix;
        ::rw::math::fpu::Matrix44Template<float> floatAlignedMatrix;

        doubleUnalignedMatrix.Set(
            0, 1, 0, 0,
           -1, 0, 0, 0,
            2, 3, 4, 0,
            0, 1, 2, 3
            );
        floatUnalignedMatrix.Set(
            0, 1, 0, 0,
           -1, 0, 0, 0,
            2, 3, 4, 0,
            0, 1, 2, 3
            );
        doubleAlignedMatrix.Set(
            0, 1, 0, 0,
           -1, 0, 0, 0,
            2, 3, 4, 0,
            0, 1, 2, 3
            );
        floatAlignedMatrix.Set(
            0, 1, 0, 0,
           -1, 0, 0, 0,
            2, 3, 4, 0,
            0, 1, 2, 3
            );

        Matrix44 ref;
        ref.Set(
            0, 1, 0, 0,
           -1, 0, 0, 0,
            2, 3, 4, 0,
            0, 1, 2, 3
            );

        Matrix44 test_doubleUnalignedMatrix(doubleUnalignedMatrix);
        Matrix44 test_floatUnalignedMatrix(doubleUnalignedMatrix);
        Matrix44 test_doubleAlignedMatrix(doubleUnalignedMatrix);
        Matrix44 test_floatAlignedMatrix(doubleUnalignedMatrix);

        Validate(IsSimilar(test_doubleUnalignedMatrix, ref) &&
            IsSimilar(test_floatUnalignedMatrix, ref) &&
            IsSimilar(test_doubleAlignedMatrix, ref) &&
            IsSimilar(test_floatAlignedMatrix, ref));

#endif



        SetFunctionName("Matrix44(const FloatClass m[16])");
#ifdef HOST_TESTING

        MakeVectorIntrinsic(fVec0, 2.0f, 3.0f, 4.0f, 5.0f);
