        MakeVectorIntrinsic(fVec2, 10.0f, 11.0f, 12.0f, 13.0f);
        MakeVectorIntrinsic(fVec3, 14.0f, 15.0f, 16.0f, 17.0f);
        union FourVectorIntrinsicUnion
        {
            VectorIntrinsic vectors[4];
            float floatData[16];
        };
        FourVectorIntrinsicUnion data;
        data.vectors[0] = fVec0;
        data.vectors[1] = fVec1;
        data.vectors[2] = fVec2;
        data.vectors[3] = fVec3;
        float *fPtr = &data.floatData[0];
