SetFunctionName("Mult(const Vector4 &v, const Matrix44 &m)");

Matrix44 m;
Vector4 v4, ra;
v4.Set(6.0f, -1.0f, -3.0f, 1.0f);
m.Set(2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f, 8.0f, 9.0f, 10.0f, 11.0f, 12.0f, 13.0f, 14.0f, 15.0f, 16.0f, 17.0f);
Vector4 r = Mult(v4, m); // test with non-aliasing

ra.Set(6.0f, -1.0f, -3.0f, 1.0f);
ra = Mult(ra, m);  // test with aliasing

Vector4 ref(
          m.GetElem(0, 0) * v4.X() + m.GetElem(1, 0) * v4.Y() + m.GetElem(2, 0) * v4.Z() + m.GetElem(3, 0) * v4.W(),
          m.GetElem(0, 1) * v4.X() + m.GetElem(1, 1) * v4.Y() + m.GetElem(2, 1) * v4.Z() + m.GetElem(3, 1) * v4.W(),
          m.GetElem(0, 2) * v4.X() + m.GetElem(1, 2) * v4.Y() + m.GetElem(2, 2) * v4.Z() + m.GetElem(3, 2) * v4.W(),
          m.GetElem(0, 3) * v4.X() + m.GetElem(1, 3) * v4.Y() + m.GetElem(2, 3) * v4.Z() + m.GetElem(3, 3) * v4.W());

Validate(IsSimilar(r, ref) && IsSimilar(ra, ref));





SetFunctionName("Mult(const Matrix44 &a, const Matrix44 &b)");

Matrix44 a, b, r, ra, ref;

a.Set(2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f, 8.0f, 9.0f, 10.0f, 11.0f, 12.0f, 13.0f, 14.0f, 15.0f, 16.0f, 17.0f);
b.Set(4.0f, 3.0f, 4.0f, 1.0f, 6.0f, 7.0f, 8.0f, 1.0f, 10.0f, 11.0f, 12.0f, 1.0f, 14.0f, 15.0f, 16.0f, 17.0f);
ra.Set(2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f, 8.0f, 9.0f, 10.0f, 11.0f, 12.0f, 13.0f, 14.0f, 15.0f, 16.0f, 17.0f);


r = Mult(a, b); // test with non-aliasing

ra = Mult(ra, b);  // test with aliasing

for (int32_t i = 0; i < 4; ++i)
{
    ref.SetElem(i, 0, a.GetElem(i, 0) * b.GetElem(0, 0) + a.GetElem(i, 1) * b.GetElem(1, 0) + a.GetElem(i, 2) * b.GetElem(2, 0) + a.GetElem(i, 3) * b.GetElem(3, 0) );
    ref.SetElem(i, 1, a.GetElem(i, 0) * b.GetElem(0, 1) + a.GetElem(i, 1) * b.GetElem(1, 1) + a.GetElem(i, 2) * b.GetElem(2, 1) + a.GetElem(i, 3) * b.GetElem(3, 1) );
    ref.SetElem(i, 2, a.GetElem(i, 0) * b.GetElem(0, 2) + a.GetElem(i, 1) * b.GetElem(1, 2) + a.GetElem(i, 2) * b.GetElem(2, 2) + a.GetElem(i, 3) * b.GetElem(3, 2) );
    ref.SetElem(i, 3, a.GetElem(i, 0) * b.GetElem(0, 3) + a.GetElem(i, 1) * b.GetElem(1, 3) + a.GetElem(i, 2) * b.GetElem(2, 3) + a.GetElem(i, 3) * b.GetElem(3, 3) );
}

Validate(IsSimilar(r, ref) && IsSimilar(ra, ref));





