    -0.8149562f,   0.5008597f,   0.2915235f,    0.0f,
    -0.4312790f,  -0.1881537f,  -0.8823812f,    0.0f,
    -0.3870979f,  -0.8448300f,   0.3693473f,    0.0f,
     3.0000000f,   2.5000000f,   6.0000000f,    1.0f
    );
Vector3 vec[3] =
{
    Vector3( 1.0f, 2.0f, 3.0f ),
    Vector3( 3.0f, -2.0f, 1.0f ),
    Vector3( 9.0f, -2.0f, 8.0f )
};
