SetFunctionName("Mult3x3(const Vector4 &v, const Matrix44 &m)");

Matrix44 m;
Vector4 v4, r;

m.Set(
        2.0f,  3.0f,  4.0f,  5.0f,
        6.0f,  7.0f,  8.0f,  9.0f,
       10.0f, 11.0f, 12.0f, 13.0f,
       14.0f, 15.0f, 16.0f, 17.0f
     );
v4.Set(6, -1, -3, 2);

Vector4 ref(
          m.GetElem(0, 0) * v4.X() + m.GetElem(1, 0) * v4.Y() + m.GetElem(2, 0) * v4.Z(),
          m.GetElem(0, 1) * v4.X() + m.GetElem(1, 1) * v4.Y() + m.GetElem(2, 1) * v4.Z(),
          m.GetElem(0, 2) * v4.X() + m.GetElem(1, 2) * v4.Y() + m.GetElem(2, 2) * v4.Z(),
          v4.W());

r = Mult3x3(v4, m);

Validate(IsSimilar(r, ref));





SetFunctionName("Mult3x3(const Vector4 &v, const Matrix44 &m)");

Matrix44 m;
Vector3 v3, r;

m.Set(
    2.0f,  3.0f,  4.0f,  5.0f,
    6.0f,  7.0f,  8.0f,  9.0f,
    10.0f, 11.0f, 12.0f, 13.0f,
    14.0f, 15.0f, 16.0f, 17.0f
    );
