SetFunctionName("Matrix44FromLookAtLH(Vector3 lookAt, Vector3 up, Vector3 eyePosition)");

Vector3 lookAt(1.0f, 11.0f, 17.0f);
Vector3 eyePoint(3.0f, -7.0f, 11.0f);
Matrix44 viewMat(Matrix44FromLookAtLH(lookAt, GetVector3_YAxis(), eyePoint ));
Vector3 lookResult = TransformPoint(lookAt, viewMat);
Vector3 eyeResult = TransformPoint(eyePoint, viewMat);

Vector3 refLook = Vector3((float_test_type)0.0f, (float_test_type)0.0f, Magnitude(lookAt-eyePoint) );
Vector3 refEye = Vector3((float_test_type)0.0f, (float_test_type)0.0f, (float_test_type)0.0f );

Validate(
    IsSimilar(lookResult, refLook, (float_test_type)0.001f) &&
    IsSimilar(eyeResult, refEye, (float_test_type)0.001f)
);



