        Matrix44 mat(Matrix44FromPerspectiveOffCenterLH(l, r, b, t, zn, zf));
#else
        Matrix44 mat(Matrix44FromPerspectiveOffCenterLH<FloatType>(l, r, b, t, zn, zf));
#endif

        Vector4 minVec(l, b, zn, (float_test_type)1.0f);
        Vector4 maxVec(r, t, zf, (float_test_type)1.0f);
        for(int i=0;i<8;i++)
        {
            bool xBool = (i&1)!=0;
            bool yBool = (i&2)!=0;
            bool zBool = (i&4)!=0;
            Vector4 testVector( Select(Mask4(xBool, yBool, zBool, true), maxVec, minVec ) );
            Vector4 result = DivideByW(testVector * mat);

            // Only test x or y values when at the near plane.
            if( !zBool )
            {
                success &= IsSimilar((float)result.X(), xBool ? 1.0f : -1.0f );
                success &= IsSimilar((float)result.Y(), yBool ? 1.0f : -1.0f );
            }
            success &= IsSimilar((float)result.Z(), zBool ? 1.0f: 0.0f );
        }

        Validate(success);



        SetFunctionName("Matrix44FromPerspectiveOffCenterRH(l, r, b, t, zn, zf)");

        bool success = true;
        float_test_type l = -3.0f;
        float_test_type r = 5.0f;
        float_test_type t = 6.0f;
        float_test_type b = -8.0f;
        float_test_type zn = 10.0f;
        float_test_type zf = 80.0f;

#if defined HOST_TESTING
        Matrix44 mat(Matrix44FromPerspectiveOffCenterRH(l, r, b, t, zn, zf));
#else
        Matrix44 mat(Matrix44FromPerspectiveOffCenterRH<FloatType>(l, r, b, t, zn, zf));
#endif

        Vector4 minVec(l, b, -zn, (float_test_type)1.0f);
        Vector4 maxVec(r, t, -zf, (float_test_type)1.0f);
        for(int i=0;i<8;i++)
        {
            bool xBool = (i&1)!=0;
            bool yBool = (i&2)!=0;
            bool zBool = (i&4)!=0;
            Vector4 testVector( Select(Mask4(xBool, yBool, zBool, true), maxVec, minVec ) );
            Vector4 result = DivideByW(testVector * mat);

            // Only test x or y values when at the near plane.
            if( !zBool )
            {
                success &= IsSimilar((float)result.X(), xBool ? 1.0f : -1.0f );
                success &= IsSimilar((float)result.Y(), yBool ? 1.0f : -1.0f );
            }
            success &= IsSimilar((float)result.Z(), zBool ? 1.0f: 0.0f );
        }

        Validate(success);





